\label{thm:mvf}
    Given $p\in[1,\8]\cap(n/2,\8]$, there exists $C\geq 1$ such that for $u\in C^2(B_1)$ we have that\footnote{Given $a\in {\mathbb R}$, we denote its positive and negative parts respectively as $a_+ = \max\{a,0\}$ and $a_-=\max\{-a,0\}$, such that $a=a_+-a_-$.}
    \[
    \fint_{B_1} u \leq u(0) + C\|(\Delta u)_+\|_{L^p(B_1)}.
    \]

For any directional derivative $v := \partial_e u$, with respect to a unit direction $e\in \partial B_1$, we have that $\Delta v = \partial_e(\Delta u)$ in $\Omega$. By applying the proof of Theorem \ref{thm:int_hold_est} to $v$ we get that for any $B_r(x_0)\subseteq\Omega$
    \begin{align*}
    r^\alpha[v]_{C^{0,\alpha}(B_{r/12}(x_0))} &\leq C\1\operatorname*{osc}_{B_{r/4}(x_0)}v + r^{2-n/p}\|\partial_e(\Delta u)\|_{L^p(B_{r/4}(x_0))}\2\\
    &\leq C\1\|Du\|_{L^\8(B_{r/4}(x_0))}+r^{-1}\|D(\Delta u)\|_{L^p(\Omega)}^{(3-n/p)}\2.
    \end{align*}
    By taking the supremum over $e \in \partial B_1$ on the left-hand side and multiplying by $r$
    \begin{align}\label{eq:6}
    r^{1+\alpha}[Du]_{C^{0,\alpha}(B_{r/12}(x_0))} \leq C\1r\|Du\|_{L^\8(B_{r/4}(x_0))}+\|D(\Delta u)\|_{L^p(\Omega)}^{(3-n/p)}\2.
    \end{align}

    By applying Lemma \ref{lem:inter} to $w(x) = u((r/2)x+x_0)$ with some $\delta\in(0,1/2)$ to be fixed sufficiently small
    \begin{align*}
    r\|Du\|_{L^\8(B_{r/4}(x_0))} &= \|Dv\|_{L^\8(B_{1/2})}\\
    &\leq C\operatorname*{osc}_{B_1}v + \delta^\alpha[Dv]_{C^{0,\alpha}(B_1)}\\
    &\leq C\operatorname*{osc}_{\Omega} u + \delta^\alpha r^{1+\alpha} [Du]_{C^{0,\alpha}(B_{r/2}(x_0))}\\
    &\leq C\operatorname*{osc}_{\Omega} u + \delta^\alpha [Du]_{C^{0,\alpha}(\Omega)}^{(1+\alpha)}.
    \end{align*}
    Substituting this interpolation in \eqref{eq:6}
    \[
    r^{1+\alpha}[Du]_{C^{0,\alpha}(B_{r/12}(x_0))} \leq C\1\operatorname*{osc}_{\Omega} u + \delta^\alpha [Du]_{C^{0,\alpha}(\Omega)}^{(1+\alpha)} + \|D(\Delta u)\|^{(3-n/p)}_{L^p(\Omega)}\2.
    \]
    Taking the supremum over $B_r(x_0)\subseteq\Omega$ and using Lemma \ref{lem:holder_weight}
    \[
    [Du]^{(1+\alpha)}_{C^{0,\alpha}(\Omega)} \leq C\1\operatorname*{osc}_{\Omega} u + \delta^\alpha [Du]^{(1+\alpha)}_{C^{0,\alpha}(\Omega)} + \|D(\Delta u)\|^{(3-n/p)}_{L^p(\Omega)}\2.
    \]
    By finally choosing $\delta$ sufficiently small, the term $\delta^\alpha[Du]^{(1+\alpha)}_{C^{0,\alpha}(\Omega)}$ gets absorbed by the left-hand side of the inequality.

\label{rmk:lin}
    The Pucci operators provide an indirect way to address equations of the form $A:D^2u=f$ without an explicit characterization of the coefficients given by the matrix-valued function $A$, in addition to uniform ellipticity. Indeed, for $f\in C(\Omega)$ we have that $u\in C^2(\Omega)$ satisfies
    \[
    \mathcal M^-_{\lambda,\Lambda}(D^2u)\leq f \leq \mathcal M^+_{\lambda,\Lambda}(D^2u) \text{ in $\Omega$}
    \]
    if and only if there exists $A\colon\Omega\to{\mathbb R}^{n\times n}_{\text{sym}}$ such that $\lambda I\leq A\leq \Lambda I$ and $A:D^2u=f$ in $\Omega$.

\label{rmk:lin3}
Let $f\colon\Omega\to[0,\8)$. The equations
\begin{align}\label{eq:11}
\begin{cases}
\mathcal M^-_{\lambda,\Lambda}(D^2u) \leq f \text{ in } \Omega,\\
\mathcal M^+_{\lambda,\Lambda}(D^2u) \geq -f \text{ in } \Omega,
\end{cases}
\end{align}
are equivalent to $|A:D^2u| \leq f$, for some $A\colon\Omega\to{\mathbb R}^{n\times n}_{\text{sym}}$ with $\lambda I\leq A\leq \Lambda I$. In particular, the equations appearing in Remark \ref{rmk:lin} imply \eqref{eq:11}

To justify this claim, consider $A^\pm\colon\Omega\to{\mathbb R}^{n\times n}_{\text{sym}}$ such that $A^\pm:D^2u = \mathcal M^\pm_{\lambda,\Lambda}(D^2u)$. Then \eqref{eq:11} means that the intervals $[-f,f]$ and $[A^-:D^2u,A^+:D^2u]$ must intercept at least at one point. For some $t\in[0,1]$ we see that $A = (1-t)A^-+tA^+$ satisfies $|A:D^2u| \leq f$.

Consider the family of paraboloids
    \[
    \varphi_{y_0}(x) := -\frac{1}{2}|x-y_0|^2 + \frac{1}{2}\1\frac{3}{4}\2^2 \leq 1.
    \]
    Letting $\theta := 1/4$, we get that for every $y_0\in B_{1/4}$ we have $\varphi_{y_0}(0) > \theta$ and $\varphi_{y_0} < 0$ in ${\mathbb R}^n \setminus B_1$. Together with the hypotheses $u(0) \leq \theta$ and $\inf_{B_1} u\geq 0$, they imply that for every $y_0\in B_{1/4}$
    \begin{align}\label{eq:2}
    \emptyset \neq \operatorname*{argmin} (u - \varphi_{y_0}) \subseteq \{u\leq 1\}\cap B_1.        
    \end{align}
    (Figure \ref{fig:abp}). Therefore, the result would follow from a lower bound on the measure of the contact set $A = \bigcup_{y_0\in B_{1/4}}\operatorname*{argmin} (u - \varphi_{y_0})$.

\begin{figure}
    \centering
    \includegraphics[width=0.8\textwidth]{abp6.pdf}
    \caption{The paraboloids are arranged such that for $y_0 \in B_{1/4}$ it happens that $\varphi_{y_0}(0) > \theta$, and $\varphi_{y_0}<0$ in ${\mathbb R}^n\setminus B_1$. Hence a positive function that dips below $\theta$ at the origin must necessarily cross all of these paraboloids. By translating each paraboloid downwards we obtain a contact point in $\{u\leq 1\}\cap B_1$.}
    \label{fig:abp}
\end{figure}

    Consider now the mapping $T\colon A\to B_{1/4}$ defined such that $T(x_0)=x_0+Du(x_0)$. Equivalently, $y_0=T(x_0)$ is the center of the paraboloid $\varphi_{y_0}$ such that $x_0 \in \operatorname*{argmin}(u-\varphi_{y_0})$. By \eqref{eq:2} it also follows that $T$ is surjective. We finally observe that $DT = I+D^2u\geq 0$ on the contact set $A$, just by definition of the contact set and the second derivative test. 

    Now we will use the uniform ellipticity over the contact set. For every $x_0\in A$ we already have that the eigenvalues of $D^2u(x_0)$ are bounded from below by $-1$, then for any positive eigenvalue $e\in \operatorname{eig}(D^2u(x_0))$ we must have $\lambda e \leq (n-1)\Lambda + f(x_0)$. This means that $\det(D^2u+I) \leq C(1+f^n)$ in $A$ for some $C\geq1$ depending on the dimension $n$ and the ellipticity constants.

    By the area formula and the hypothesis $\|f\|_{L^n(B_1)}\leq \delta$,
    \[
    |B_{1/4}| \leq \int_{A}\det(D^2u+I) \leq C|A| + C\delta^n.
    \]
    By choosing $\delta$ sufficiently small we can absorb the term $C\delta^n$ on the left-hand side and get the desired estimate for $\eta := |B_{1/4}|/(2C)$.

Consider the family of test functions (Figure \ref{fig:abp4})
    \[
    \varphi_{y_0}(x) := C_0\frac{q(|x-y_0|)-q(1-\rho/2)}{q(1/2+\rho/2)-q(1-\rho/2)}, \qquad q(r) := \min\{r^{-\alpha},(\rho/2)^{-\alpha}\},
    \]
    where $C_0,\alpha\geq 1$ will be chosen sufficiently large. We see that for any $y_0 \in B_{\rho/2}$, we have $\inf_{B_{1/2}}\varphi_{y_0} \geq 1$, and $\sup_{{\mathbb R}^n\setminus B_1}\varphi_{y_0} \leq 0$.

    Let $M := \max_{{\mathbb R}^n} \varphi_{y_0}$. If we assume by contradiction that $\inf_{B_{\rho}}u > M$ we obtain that for each $y_0\in B_{\rho/2}$
    \begin{align}
        \label{eq:3}
    \emptyset\neq \operatorname*{argmin}(u-\varphi_{y_0}) \subseteq B_1\setminus \overline{B_{\rho}}.
    \end{align}

    \begin{figure}
        \centering
        \includegraphics[width=0.8\textwidth]{abp4.pdf}
        \caption{The test functions are arranged such that for $y_0\in B_{\rho/2}$, they are smooth in $B_1\setminus \overline{B_\rho}$, remain above one in $\overline{B_{1/2}}$, and below zero in ${\mathbb R}^n\setminus B_1$. Hence, a positive function that goes above their maximum $M$ in $\overline{B_\rho}$, and dips below one in $\overline{B_{1/2}}$ must necessarily cross all the functions in $B_1\setminus \overline{B_\rho}$. As in Lemma \ref{lem:abp}, we can translate the test functions downwards until the touch $u$ at some point in $B_1\setminus \overline{B_\rho}$.}
        \label{fig:abp4}
    \end{figure}

    Let $A = \bigcup_{y_0 \in B_{\rho/2}} \operatorname*{argmin}(u-\varphi_{y_0})$, and $T:A\to B_{\rho/2}$ such that $T(x_0)=y_0$ if $x_0 \in \operatorname*{argmin} (u-\varphi_{y_0})$. This mapping is surjective due to \eqref{eq:3} and gets computed from the tangency relation at the contact point
    \[
    T(x_0) = x_0 - D\varphi_0^{-1}(Du(x_0)) = x_0 + C_0C_1\alpha|Du(x_0)|^{-(2+\alpha)/(1+\alpha)}Du(x_0).
    \]
    where $C_1:= (q(1/2+\rho/2)-q(1-\rho/2))^{-1}$.

    Let $\Phi(x) := D^2\varphi_0(x-T(x))$. By the area formula
    \begin{align}\label{eq:area}
        |B_{\rho/2}| \leq \int_A |\det(DT)| = \int_A |\det(I - \Phi^{-1} D^2u)|.
    \end{align}

    To estimate the integrand we use the following fact from linear algebra: For $N_1,N_2 \in {\mathbb R}^{n\times n}_{\text{sym}}$ such that $\det N_1\neq 0$\footnote{For $M\in {\mathbb R}^{n\times n}$, we denote $|M|_{\text{op}} := \sup_{|x|=1}|Mx|$. If $M$ is symmetric then we have that
    \[
    |M|_{\text{op}} = \max\{|e| \ | \ e\in \operatorname{eig}(M)\}.
    \]}
    \begin{align*}
    |\det(I - N_1^{-1}N_2)| &= \sqrt{\det((I-N_1^{-1}N_2)^T(I-N_1^{-1}N_2))}\\
    &\leq |I - N_2N_1^{-1} - N_1^{-1}N_2 + N_2N_1^{-2}N_2|_{\text{op}}^{n/2}\\
    &\leq (1+2|N_1^{-1}|_{\text{op}}|N_2|_{\text{op}}+|N_1^{-1}|_{\text{op}}^2|N_2|_{\text{op}}^2)^{n/2}\\
    &\leq C(1+|N_1^{-1}|_{\text{op}}^n|N_2|_{\text{op}}^n)\\
    &= C\11+\1\frac{\max_{e\in \operatorname{eig}(N_2)}|e|}{\min_{e\in \operatorname{eig}(N_1)}|e|}\2^n\2.
    \end{align*}

    For $z \in {\mathbb R}^n\setminus \overline{B_{\rho/2}}$ we compute
    \[
    D^2\varphi_0(z) = C_0C_1\alpha|z|^{-\alpha-2}\1(\alpha+2)\frac{z\otimes z}{|z|^2} - I\2.
    \]
    From this we get that the eigenvalues of $D^2\varphi_0(z)$ are: $C_0C_1\alpha|z|^{-\alpha-2}(\alpha+1)$ with single multiplicity, and $-C_0C_1\alpha|z|^{-\alpha-2}$ with multiplicity $(n-1)$. 

    For $x_0 \in A$ and $y_0=T(x_0)$
    \begin{align*}
    f(x_0) \geq \mathcal M^-_{\lambda,\Lambda}(D^2\varphi_{y_0}(x_0)) = C_0C_1\alpha|x_0-y_0|^{-\alpha-2}(\lambda (\alpha+1)-\Lambda(n-1)) .
    \end{align*}
    We can make the right-hand side positive by fixing $\alpha:=\Lambda n/\lambda$. Then we can also make the right-hand side $\geq 1$ by fixing $C_0$ large enough, depending on $\rho$ and $\alpha$.

    Once we have fixed the parameters $\alpha$, $C_0$, and hence also $M$; we notice that $|D^2\varphi_{y_0}|_{\text{op}}$ and $|(D^2\varphi_{y_0})^{-1}|_{\text{op}}$ are bounded over $B_1\setminus \overline{B_{\rho}}\supseteq A$, uniformly with respect to $y_0\in B_{\rho/2}$. The eigenvalues of $D^2u(x_0)$ are bounded from below by $-|D^2\varphi_{y_0}(x_0)|_{\text{op}}$. On the other hand, the equation provides an upper bound for the positive eigenvalues $e \in \operatorname{eig}(D^2u(x_0))$ given by $\lambda e \leq \Lambda (n-1)|D^2\varphi_{y_0}(x_0)|_{\text{op}} + f(x_0)$.

    Putting together the information about the eigenvalues of $N_1= \Phi = D^2\varphi_{y_0}$ and $N_2= D^2u$, and using that $A\subseteq \{f\geq 1\}$, we conclude that $|DT| = |\det(I - \Phi^{-1} D^2u)| \leq Cf^n$ in $A$. Due to \eqref{eq:area} we obtain $|B_{\rho/2}|\leq C\|f\|_{L^n(B_1)}^n \leq C\delta^n$, however this is a contradiction if we finally fix $\delta$ sufficiently small.

Let us see that the given choice of $\mu$ and $r$ guarantees that
    \begin{align}
        \label{eq:5}
    m &:= \max\{(\varphi_0^1-\varphi_{x_0}^2)(x) \ | \ x\in \overline{B_\mu}\}\\
    \notag &\leq \min\{(\varphi_0^1-\varphi_{x_0}^2)(x) \ | \ x\in {\mathbb R}^n\setminus\overline{B_{(1-\mu)/2}(x_0)}\}\\
    \notag &\leq 1.
    \end{align}
    Once this is done, we observe that the paraboloid $\varphi^2_{x_0}+m$ is above $\varphi_0^1$ over $\overline{B_\mu}$ and below $\varphi_0^1$ outside $\overline{B_{(1-\mu)/2}(x_0)}$. Hence, the hypotheses on $u$ imply that $\varphi_{x_0}^2+m$ must cross $u$ in $\overline{B_{(1-\mu)/2}(x_0)}$. By lowering the paraboloid we find a contact point in $\overline{B_{(1-\mu)/2}(x_0)}$. See Figure \ref{fig:abp_deg2}.

\begin{figure}
    \centering
    \includegraphics[width=0.8\textwidth]{abp_deg2.pdf}
    \caption{We arrange $\mu$, $r$, and $m$ such that the graph of $u$ enters the region $\{(x,y) \in {\mathbb R}^n \times {\mathbb R} \ | \ \varphi_0^1(x) \leq y\leq  \varphi_{x_0}^2(x)+m\} \subseteq B_{(1-\mu)/2}(x_0)\times (-\8,1]$.}
    \label{fig:abp_deg2}
\end{figure}

    We compute
    \begin{align*}
    \varphi_0^1(x)-\varphi_{x_0}^2(x) &= -\frac{1}{2}|x|^2 + |x-x_0|^2 = \frac{1}{2}|x|^2 - 2x\cdot x_0 + r^2 = \frac{1}{2}|x-2x_0|^2-r^2.
    \end{align*}

    The maximum of this convex paraboloid over $\overline{B_\mu}$ is achieved at the furthest boundary point from $2x_0$
    \[
    \max\{(\varphi_0^1-\varphi_{x_0}^2)(x) \ | \ x\in \overline{B_\mu}\} = \frac{1}{2}(\mu+2r)^2-r^2.
    \]

    Given that $r \leq (1-\mu)/2$, the vertex $2x_0$ falls in $\overline{B_{(1-\mu)/2}(x_0)}$, then the minimum of $(\varphi_0^1-\varphi_{x_0}^2)$ over the complement of $\overline{B_{(1-\mu)/2}(x_0)}$ is attained at the closest boundary point from $2x_0$. In particular it is less than 1
    \[
    \min\{(\varphi_0^1-\varphi_{x_0}^2)(x) \ | \ x\in {\mathbb R}^n\setminus\overline{B_{(1-\mu)/2}(x_0)}\} \leq \1\frac{1-\mu}{2}\2^2<1.
    \]
    Moreover,
    \[
    \min\{(\varphi_0^1-\varphi_{x_0}^2)(x) \ | \ x\in {\mathbb R}^n\setminus\overline{B_{(1-\mu)/2}(x_0)}\} = \frac{1}{2}\1\frac{1-\mu}{2}-r\2^2-r^2.
    \]

    Finally we see that $\mu+2r = 1/3 = \frac{1-\mu}{2}-r$ guarantees \eqref{eq:5}.
